using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;
namespace Musikbox {public partial class Controller {
 readonly Dictionary<string,FileTagAction> fileActions=new Dictionary<string,FileTagAction>();
 async void SaveFileChanges(List<TagChange> plan,string name){if(busy||plan.Count==0)return;Song anchor=editedSong??SelectedSong;cancel=new System.Threading.CancellationTokenSource();var token=cancel.Token;SetBusy(true);try{var action=await System.Threading.Tasks.Task.Run(()=>FileTagAction.Apply(plan,Path.Combine(PortablePaths.Data,"Datei-Rueckgaengig"),()=>token.ThrowIfCancellationRequested()));fileActions[action.Id]=action;InvalidateArtwork();Changed("Dateiaktion:"+action.Id,true);PopulateLibrary();PreserveEditedSongInLibrary(anchor);if(playerSong!=null&&plan.Any(c=>String.Equals(c.Source,playerSong.Source,StringComparison.OrdinalIgnoreCase)))RefreshPlayerArtwork();v.Status.Text=name+" · "+plan.Count+" Dateien gespeichert";}catch(OperationCanceledException){v.Status.Text=name+" abgebrochen; Originaldateien unverändert.";}catch(Exception ex){AppMessage.Show(v,ex.Message,name+" konnte nicht gespeichert werden");}finally{cancel.Dispose();cancel=null;SetBusy(false);}}
 DataGridView PreviewGrid(){var grid=new StudioSongGrid{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,RowHeadersVisible=false};grid.Columns.Add("Datei","Datei");grid.Columns.Add("Neu","Vorschau");return grid;}
 void OpenTrackNumbers(){var songs=SelectedSongs();if(songs.Count==0){AppMessage.Show(v,"Bitte die zu nummerierenden Titel markieren.");return;}using(var dialog=new ModernForm{Text="Track-Nummern-Assistent",Width=780,Height=550,StartPosition=FormStartPosition.CenterParent}){var options=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,Padding=new Padding(12),WrapContents=true};var start=new StudioNumericUpDown{Minimum=0,Maximum=999999,Value=1,Width=90};var total=new CheckBox{Text="Gesamtzahl speichern",AutoSize=true};var zeros=new CheckBox{Text="Führende Nullen",AutoSize=true};var reset=new CheckBox{Text="Zähler für jedes Verzeichnis zurücksetzen",AutoSize=true};options.Controls.Add(new Label{Text="Beginnen bei Tracknummer:",AutoSize=true,Padding=new Padding(0,6,0,0)});options.Controls.Add(start);options.Controls.Add(total);options.Controls.Add(zeros);options.Controls.Add(reset);var grid=PreviewGrid();var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=54,Padding=new Padding(12)};List<TagChange> plan=null;Action preview=()=>{try{plan=TrackNumbering.Plan(songs,(int)start.Value,total.Checked,zeros.Checked,reset.Checked);grid.Rows.Clear();foreach(var c in plan)grid.Rows.Add(c.Source,c.Description);}catch(Exception ex){plan=null;AppMessage.Show(dialog,ex.Message);}};bottom.Controls.Add(MainView.StudioButton("Tracknummern speichern",()=>{try{preview();if(plan==null)return;SaveFileChanges(plan,"Tracknummern");dialog.DialogResult=DialogResult.OK;}catch(Exception ex){AppMessage.Show(dialog,ex.Message);}},true));bottom.Controls.Add(MainView.StudioButton("Abbrechen",()=>dialog.Close()));dialog.Controls.Add(grid);dialog.Controls.Add(options);dialog.Controls.Add(bottom);start.ValueChanged+=(s,e)=>preview();foreach(var c in new[]{total,zeros,reset})c.CheckedChanged+=(s,e)=>preview();ModernTheme.Apply(dialog);preview();dialog.ShowDialog(v);}}
 void OpenTagConversion(){var panel=ModulePage("Tag-Editor","Direkt mit der zentralen Titelauswahl arbeiten. Metadaten rechts bearbeiten und mit Speichern in die Originaldateien schreiben.");var options=ModuleButtons(panel);
 var mode=new StudioComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=220};mode.Items.AddRange(new object[]{"Tag → Dateiname","Dateiname → Tag","Dateiname → Dateiname"});mode.SelectedIndex=0;
 var pattern=new StudioTextBox{Text=OutputFormatSettings.Pattern,Width=320};var inputPattern=new StudioTextBox{Text="%artist% - %title%",Width=260,Visible=false};var inputLabel=new Label{Text="Eingabemuster",AutoSize=true,Visible=false};options.Controls.Add(mode);options.Controls.Add(inputLabel);options.Controls.Add(inputPattern);mode.SelectedIndexChanged+=(s,e)=>inputLabel.Visible=inputPattern.Visible=mode.SelectedIndex==2;options.Controls.Add(new Label{Text="Ausgabeformat / Muster",AutoSize=true});options.Controls.Add(pattern);
 Action savePattern=()=>{OutputFormatSettings.Pattern=pattern.Text;v.TagEditor.ApplyFormat();v.RefreshStudioNow();};pattern.Validated+=(s,e)=>Run(savePattern);
 options.Controls.Add(MainView.StudioButton("Platzhalter auswählen …",()=>{using(var d=new OutputFormatView(pattern.Text))if(d.ShowDialog(v)==DialogResult.OK){pattern.Text=d.Pattern;savePattern();}}));
 options.Controls.Add(MainView.StudioButton("Änderungen speichern",()=>Run(()=>{savePattern();var songs=SelectedSongs();var plan=TagConversion.Plan(songs,mode.SelectedIndex,mode.SelectedIndex==2?inputPattern.Text:pattern.Text,pattern.Text,"");SaveFileChanges(plan,"Tag-Editor");}),true));options.Controls.Add(MainView.StudioButton("Metadaten bearbeiten …",()=>Run(EditTags)));v.ShowModule(panel,paths=>SelectWorkingPaths(paths));
 }
}}
